<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { Users, UserPlus, Search, X, ShieldCheck } from '@lucide/vue'
import { api } from '../api'
import { roleLabels } from '../composables/auth'
const users=ref([]), loading=ref(true), error=ref(''), notice=ref(''), roleDrafts=reactive({}), search=ref(''), showForm=ref(false), busy=ref(false)
const form=reactive({ displayName:'',studentNumber:'',email:'',password:'',role:'Member',canCreateCourses:false })
const filtered=computed(()=>users.value.filter(u=>`${u.displayName} ${u.email} ${roleLabels[u.role]}`.toLowerCase().includes(search.value.toLowerCase())))
onMounted(async()=>{try{users.value=await api('/accounts')}catch(e){error.value=e.message}finally{loading.value=false}})
async function create(){busy.value=true;error.value='';try{const user=await api('/accounts',{method:'POST',body:form});users.value.push(user);Object.assign(form,{displayName:'',studentNumber:'',email:'',password:'',role:'Member',canCreateCourses:false});showForm.value=false}catch(e){error.value=e.message}finally{busy.value=false}}
function editPermission(user,key,value){roleDrafts[user.id]={role:user.role,canCreateCourses:user.canCreateCourses,...roleDrafts[user.id],[key]:value}}
function changed(user){const edit=roleDrafts[user.id];return edit && (edit.role!==user.role || edit.canCreateCourses!==user.canCreateCourses)}
async function saveRole(user){busy.value=true;error.value='';notice.value='';try{const edit=roleDrafts[user.id];await api(`/accounts/${user.id}/permissions`,{method:'PUT',body:{...edit,expectedRole:user.role,expectedCanCreateCourses:user.canCreateCourses}});Object.assign(user,edit);delete roleDrafts[user.id];notice.value='平台管理權限與建課資格已更新；該帳號須重新登入，各課程角色保持不變。'}catch(e){error.value=e.message}finally{busy.value=false}}

</script>
<template><section class="page-heading"><div><p class="eyebrow">PEOPLE & ROLES</p><h1>讓對的人，進入同一個空間。</h1><p class="muted">管理員管理平台帳號；課程角色則由各課程設定。</p></div><button class="button primary" @click="showForm=!showForm"><UserPlus :size="17" />建立帳號</button></section>
  <p v-if="error" class="error-box" role="alert">{{ error }}</p><p v-if="notice" class="success-box" role="status">{{notice}}</p><section v-if="showForm" class="surface form-surface"><div class="section-title"><h2>建立平台帳號</h2><button class="icon-button" aria-label="關閉建立帳號" @click="showForm=false"><X :size="18" /></button></div><form class="account-create-form" @submit.prevent="create"><fieldset :disabled="busy"><div class="form-grid"><label>顯示名稱<input v-model="form.displayName" required maxlength="100" autocomplete="off" /></label><label>學號（選填）<input v-model="form.studentNumber" maxlength="40" /></label><label>電子郵件<input v-model="form.email" type="email" required maxlength="254" autocomplete="off" /></label><label>初始密碼<input v-model="form.password" type="password" required minlength="12" maxlength="128" autocomplete="new-password" placeholder="至少 12 個字元" /></label><label>平台管理權限<select v-model="form.role"><option v-for="(label,key) in roleLabels" :key="key" :value="key">{{ label }}</option></select></label><label class="choice-label"><input type="checkbox" v-model="form.canCreateCourses" />可建立課程</label></div><div class="form-bottom"><p class="field-hint">請透過適當管道將初始密碼交給本人，登入後可自行變更。</p><button class="button primary">{{ busy?'建立中…':'建立帳號' }}</button></div></fieldset></form></section>
  <section class="surface"><div class="table-toolbar"><div><h2>平台成員 <span class="count-pill">{{ users.length }}</span></h2><p class="muted">學號為唯讀；平台管理權限可修改，課程角色須另行設定。</p></div><label class="search-field"><Search :size="17" /><input v-model="search" aria-label="搜尋成員" placeholder="搜尋姓名、郵件或角色" /></label></div><p v-if="loading" class="empty-inline">載入成員中…</p><div v-else class="table-scroll"><table class="data-table"><thead><tr><th scope="col">成員</th><th scope="col">學號</th><th scope="col">電子郵件</th><th scope="col">平台管理權限</th><th scope="col">狀態</th></tr></thead><tbody><tr v-for="user in filtered" :key="user.id"><td><div class="person-cell"><span class="avatar">{{ Array.from(user.displayName).slice(0,1).join('') }}</span><strong>{{ user.displayName }}</strong></div></td><td>{{ user.studentNumber?.trim() || '(空)' }}</td><td>{{ user.email || '(空)' }}</td><td><div class="member-role-actions"><select :aria-label="`${user.displayName} 平台管理權限`" :value="roleDrafts[user.id]?.role ?? user.role" :disabled="busy" @change="editPermission(user,'role',$event.target.value)"><option v-for="(label,key) in roleLabels" :key="key" :value="key">{{label}}</option></select><label class="choice-label"><input type="checkbox" :aria-label="`${user.displayName} 可建立課程`" :checked="roleDrafts[user.id]?.canCreateCourses ?? user.canCreateCourses" :disabled="busy" @change="editPermission(user,'canCreateCourses',$event.target.checked)" />可建立課程</label><button class="button primary member-role-save" :disabled="busy || !changed(user)" @click="saveRole(user)">儲存權限</button></div></td><td><span class="status-badge"><span class="live-dot"></span>已建立</span></td></tr></tbody></table><p v-if="!filtered.length" class="empty-inline">找不到符合條件的成員。</p></div></section><p class="page-note"><ShieldCheck :size="16" />只有管理員可以存取此頁；API 也會驗證角色權限。</p></template>

<style scoped>
.member-role-actions{display:flex;align-items:center;gap:8px}
.member-role-actions select{width:110px;flex:0 0 110px;padding:8px 10px}
.member-role-save{white-space:nowrap;background:#2563eb;color:#fff;padding:9px 14px}
.member-role-save:hover{background:#1d4ed8}
</style>
